Aqui está a solução completa e eficiente em C++.

### Método
O problema consiste em escolher $K$ novas posições $B_1 < B_2 < \dots < B_K$ para os membros do grupo de forma a maximizar a soma dos brigadeiros $\sum_{j=1}^K P_{B_j}$, com a restrição de que o número mínimo de trocas entre vizinhos seja no máximo $T$. 

O número mínimo de trocas para levar os amigos das posições iniciais $A_1 < A_2 < \dots < A_K$ para as novas posições $B_1 < B_2 < \dots < B_K$ é exatamente $\sum_{j=1}^K |A_j - B_j|$.

Como o valor de cada prato é no máximo 9, a pontuação total máxima possível é $9 \times K \le 2700$. Em vez de usar $T$ no estado da programação dinâmica, podemos inverter o problema e definir:
- $dp[j][v]$: o custo mínimo (número de trocas) para posicionar os primeiros $j$ amigos acumulando exatamente $v$ brigadeiros.

Para cada prato $i$ de $1$ a $N$, decidimos se atribuímos esse prato ao $j$-ésimo amigo (com custo adicional de $|A_j - i|$ trocas) ou se deixamos esse prato vazio. A transição é calculada em ordem decrescente de $j$ e $v$, mantendo a complexidade temporal em cerca de $1.5 \times 10^{-2} \times N^3 \approx 4 \times 10^7$ operações básicas, o que executa em frações de segundo para $N \le 300$.

### Código em C++

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    long long t;
    if (!(cin >> n >> k >> t)) return 0;

    vector<int> p(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> p[i];
    }

    vector<int> a(k + 1);
    int friend_idx = 1;
    for (int i = 1; i <= n; ++i) {
        int g;
        cin >> g;
        if (g == 1) {
            a[friend_idx++] = i;
        }
    }

    int max_val = 9 * k;
    vector<vector<int>> dp(k + 1, vector<int>(max_val + 1, INF));
    dp[0][0] = 0;

    for (int i = 1; i <= n; ++i) {
        int plate_val = p[i];
        int max_j = min(i, k);
        for (int j = max_j; j >= 1; --j) {
            int dist = abs(a[j] - i);
            int current_max_val = 9 * j;
            for (int v = current_max_val; v >= plate_val; --v) {
                if (dp[j - 1][v - plate_val] != INF) {
                    dp[j][v] = min(dp[j][v], dp[j - 1][v - plate_val] + dist);
                }
            }
        }
    }

    int ans = 0;
    for (int v = max_val; v >= 0; --v) {
        if (dp[k][v] <= t) {
            ans = v;
            break;
        }
    }

    cout << ans << "\n";

    return 0;
}
```

